import{_ as i,J as a,b as n,e as r,a8 as s,f as o,L as d}from"./chunks/framework.CumEd6mW.js";const U=JSON.parse('{"title":"GR32.CPUID","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32.CPUID","entity":"GR32.CPUID","kind":"Unit","summary":"Provides hardware CPU feature detection, vendor identification, cache queries, and instruction set introspection.","title":"GR32.CPUID","date":1788949297000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32.CPUID/index.md","filePath":"api/GR32.CPUID/index.md","lastUpdated":1788949297000,"timestamp":1788949297000,"datetime":"2026-09-09T10:21:37.000Z"}'),c={name:"api/GR32.CPUID/index.md"};function p(u,e,l,P,C,h){const t=a("ApiMembers");return n(),r("div",null,[e[0]||(e[0]=s('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p>The <code>GR32.CPUID</code> unit provides comprehensive CPU detection capabilities for x86 and x64 architectures. It queries CPU vendor identification, instruction set extensions (such as MMX, SSE, SSE2..SSE4.2, AVX, AVX2, AVX-512, BMI1/2, FMA), processor topology, cache sizes, and operating system support for extended register sets (XMM/YMM).</p><p>Key capabilities provided by this unit include:</p><ul><li><strong>Vendor Identification</strong>: Enumerates CPU vendors and hypervisor virtual machines via <a href="/api/GR32.CPUID/TCPUVendor">TCPUVendor</a>.</li><li><strong>Instruction Set Feature Flags</strong>: Detects hardware SIMD and vector instruction extensions via <a href="/api/GR32.CPUID/TCPUInstructionSet">TCPUInstructionSet</a> and <a href="/api/GR32.CPUID/TCPUInstructionSet">TInstructionSupport</a>.</li><li><strong>CPU Details &amp; Cache Info</strong>: Queries CPU family, model, stepping, and L1/L2/L3 cache sizes via the <a href="/api/GR32.CPUID/TCPU">TCPU</a> record structure.</li></ul><hr>',5)),o("p",null,[d(t,{type:"members"})])])}const I=i(c,[["render",p]]);export{U as __pageData,I as default};
